 CreativeCanvas(Context c,String mode,int index){super(c);this.mode=mode;this.index=index;setContentDescription(mode.equals("story")?"Drag the story piece onto the outlined destination. The Place button provides the same action.":mode.equals("texture")?"Swipe the texture to reveal the picture":mode.equals("clay")?"Drag to pull, flatten or roll the clay":"Drawing surface. Drag to draw.");setFocusable(true);setLayerType(View.LAYER_TYPE_SOFTWARE,null);for(int i=0;i<24;i++){double a=i*Math.PI/12;cx[i]=320+(float)Math.cos(a)*155;cy[i]=360+(float)Math.sin(a)*155;}File f=draft();if(f.isFile()){Bitmap previous=BitmapFactory.decodeFile(f.toString());if(previous!=null){drawing.drawBitmap(previous,null,new Rect(0,0,640,840),p);previous.recycle();}}else if(mode.equals("texture"))fillTexture();prior=marks.copy(Bitmap.Config.ARGB_8888,false);dots=getSharedPreferences("creative",0).getInt("dots-"+index,0);if(dots>=12){dots=12;done=mode.equals("dots");}if(mode.equals("story")&&storyStep<art.stories.optJSONObject(story).optJSONArray("steps").length()&&art.stories.optJSONObject(story).optJSONArray("steps").optJSONObject(storyStep).optString("item").equals("cloud2.png")){px=530;py=110;}if(mode.equals("clay")){String saved=getSharedPreferences("creative",0).getString("clay-mesh","");if(!saved.isEmpty())try{JSONArray points=new JSONArray(saved);for(int i=0;i<24;i++){cx[i]=(float)points.getDouble(i*2);cy[i]=(float)points.getDouble(i*2+1);}}catch(JSONException ignored){}}}
