 void persist(){if(mode.equals("story"))return;if(mode.equals("dots"))getSharedPreferences("creative",0).edit().putInt("dots-"+index,dots).apply();try(FileOutputStream out=new FileOutputStream(draft())){marks.compress(Bitmap.CompressFormat.PNG,100,out);}catch(IOException e){Toast.makeText(CreativeActivity.this,"Could not save this draft",Toast.LENGTH_SHORT).show();}if(mode.equals("clay")){JSONArray a=new JSONArray();for(int i=0;i<24;i++){a.put(Float.valueOf(cx[i]));a.put(Float.valueOf(cy[i]));}getSharedPreferences("creative",0).edit().putString("clay-mesh",a.toString()).apply();}}
