 void clearDrawing(){marks.eraseColor(Color.TRANSPARENT);if(prior!=null)prior.recycle();prior=marks.copy(Bitmap.Config.ARGB_8888,false);strokes.clear();dots=0;done=false;for(int i=0;i<3;i++){sorted[i]=false;sx[i]=115+i*200;sy[i]=200;}if(mode.equals("texture"))fillTexture();if(mode.equals("clay"))for(int i=0;i<24;i++){double a=i*Math.PI/12;cx[i]=320+(float)Math.cos(a)*155;cy[i]=360+(float)Math.sin(a)*155;}persist();invalidate();}
 void undo(){if(!strokes.isEmpty()){strokes.remove(strokes.size()-1);marks.eraseColor(Color.TRANSPARENT);if(prior!=null)drawing.drawBitmap(prior,0,0,p);for(Stroke s:strokes)drawStroke(s);invalidate();}}
 void drawStroke(Stroke s){p.setColor(s.color);p.setStrokeWidth(s.width);p.setStyle(Paint.Style.STROKE);p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeJoin(Paint.Join.ROUND);drawing.drawPath(s.path,p);p.setStyle(Paint.Style.FILL);}
