 @Override protected void onDraw(Canvas real){super.onDraw(real);if(nativeStage!=null){
  if(mode.equals("story"))nativeStage.submit(storyFrame());else{Bitmap full=Bitmap.createBitmap(640,840,Bitmap.Config.ARGB_8888);render(new Canvas(full));Bitmap preview=Bitmap.createScaledBitmap(full,320,420,true);full.recycle();nativeStage.image(preview);nativeStage.submit(new SceneFrame(java.util.Collections.emptyList(),theme.background,840,"studio",done));}
  if(mode.equals("story")&&motion()&&isShown()&&hasWindowFocus())postInvalidateDelayed(33);return;
 }real.save();real.scale(getWidth()/640f,getHeight()/840f);render(real);real.restore();if((mode.equals("story")||mode.equals("fish")||mode.equals("shape"))&&motion()&&isShown()&&hasWindowFocus())postInvalidateDelayed(33);}
 SceneFrame storyFrame(){
  JSONObject ep=art.stories.optJSONObject(story);JSONArray steps=ep.optJSONArray("steps");ArrayList<SceneFrame.Node>nodes=new ArrayList<>();int length=steps.length();boolean finished=storyStep>=length;int through=Math.min(storyStep,length-1);
  for(int i=0;i<=through;i++){JSONObject step=steps.optJSONObject(i);float x=(float)step.optDouble("x",50)*6.4f,y=(float)step.optDouble("y",60)*8.4f;boolean active=i==storyStep&&!finished;
   if(active&&!placed){nodes.add(new SceneFrame.Node(8,x,y,125,125,0,theme.border,0,false));x=px;y=py;}
   else if(active&&placed){float age=motion()?Math.min(1,(SystemClock.uptimeMillis()-reactionAt)/380f):1;float ease=1-(1-age)*(1-age)*(1-age);x=px+(x-px)*ease;y=py+(y-py)*ease;}
   int color=step.optString("item").contains("pink")?0xe2a1b7:step.optString("item").contains("blue")?0x7dbbd7:new int[]{0xe4bd7e,0x8dbf9a,0xba9cc9}[i%3];
   nodes.add(SceneFrame.model(x,y,65,StoryModels.forItem(step.optString("item")),color,true));
  }
  boolean happy=finished&&endingChoice>=0;return new SceneFrame(nodes,ep.optString("theme").equals("night")?0xff303f5b:ep.optString("theme").equals("ocean")?0xff86c6cf:0xffc8e4e8,840,ep.optString("id").equals("bridge")?"bridge":ep.optString("theme","forest"),happy,endingChoice);
 }
 void render(Canvas c){c.drawColor(Color.WHITE);p.setStyle(Paint.Style.FILL);if(mode.equals("fish")){c.drawColor(0xffc4e5ed);p.setColor(0xff9dcfda);for(int i=0;i<6;i++)c.drawCircle(55+i*110,125+i%2*50,13,p);p.setColor(0xffecdcb6);c.drawOval(-100,740,780,990,p);fishX+=(foodX-fishX)*(motion()?.07f:1);fishY+=(foodY-fishY)*(motion()?.07f:1);bitmap(c,art.image(art.named("Fish")),new RectF(fishX-75,fishY-75,fishX+75,fishY+75));p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(4);p.setColor(0xff4a8c9c);c.drawCircle(foodX,foodY,20+(float)Math.sin(SystemClock.uptimeMillis()/200.)*4,p);p.setStyle(Paint.Style.FILL);return;}if(mode.equals("shape")){for(int i=0;i<3;i++){p.setColor(0xfff0edf6);c.drawRoundRect(28+i*205,500,202+i*205,690,25,25,p);p.setColor(0xffbbb5d2);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(4);drawShape(c,115+i*200,590,i,p);p.setStyle(Paint.Style.FILL);if(!sorted[i]){p.setColor(new int[]{0xff75bdb1,0xffdc95ad,0xffd5b45f}[i]);drawShape(c,sx[i],sy[i]+(motion()?(float)Math.sin(SystemClock.uptimeMillis()/550.+i)*7:0),i,p);}}label(c,done?"Every shape found a home!":"Match the shape, not just its color",320,770,0xff202941,25);return;}if(mode.equals("clay")){p.setColor(0xfff2dfcd);c.drawRoundRect(18,28,622,810,36,36,p);p.setColor(0x22634637);c.drawOval(125,540,530,610,p);Path clay=new Path();clay.moveTo(cx[0],cy[0]);for(int i=1;i<24;i++)clay.lineTo(cx[i],cy[i]);clay.close();p.setShader(new RadialGradient(255,285,360,new int[]{0xffffd8b8,ink,0xff835346},null,Shader.TileMode.CLAMP));c.drawPath(clay,p);p.setShader(null);label(c,"Your clay · drag to shape",320,725,0xff202941,26);return;}
 if(mode.equals("story")){JSONObject ep=art.stories.optJSONObject(story);p.setColor(ep.optString("theme").equals("night")?0xffd7d9ef:0xffd8eced);c.drawRect(0,0,640,840,p);p.setColor(0xffa7cead);c.drawOval(-200,520,900,1100,p);if(ep.optString("id").equals("bridge")){p.setColor(0xff83cbd9);Path stream=new Path();stream.moveTo(245,450);stream.cubicTo(200,580,325,670,240,840);stream.lineTo(430,840);stream.cubicTo(500,650,370,570,450,450);stream.close();c.drawPath(stream,p);}boolean ocean=ep.optString("theme").equals("ocean"),night=ep.optString("theme").equals("night");float bob=motion()?(float)Math.sin(SystemClock.uptimeMillis()/700.)*5:0;if(ocean){bitmap(c,art.image("webart/story/seaweed_green_a.png"),new RectF(25,500,145,780));bitmap(c,art.image("webart/story/seaweed_pink_a.png"),new RectF(490,520,625,800));bitmap(c,art.image("webart/story/fish_green.png"),new RectF(90,290+bob,240,405+bob));bitmap(c,art.image("webart/story/fish_red.png"),new RectF(380,340-bob,530,450-bob));}else{bitmap(c,art.image("webart/story/treePine.png"),new RectF(20,280,150,600));bitmap(c,art.image("webart/story/house1.png"),new RectF(440,375,625,610));String frame=motion()&&SystemClock.uptimeMillis()/500%2==0?"walk1":"walk2";bitmap(c,art.image("webart/story/player_"+frame+".png"),new RectF(115,450+bob,210,655+bob));bitmap(c,art.image("webart/story/female_"+frame+".png"),new RectF(440,475-bob,530,680-bob));if(night)bitmap(c,art.image("webart/story/moonFull.png"),new RectF(440,80,550,190));}JSONArray steps=ep.optJSONArray("steps");for(int i=0;i<storyStep;i++){JSONObject s=steps.optJSONObject(i);float x=(float)s.optDouble("x",50)*6.4f,y=(float)s.optDouble("y",60)*8.4f;float drift=motion()?(float)Math.sin(SystemClock.uptimeMillis()/650.)*4:0;bitmap(c,art.image(art.original(s.optString("item"))),new RectF(x-60,y-60+drift,x+60,y+60+drift));}JSONObject s=steps.optJSONObject(storyStep);float tx=(float)s.optDouble("x",60)*6.4f,ty=(float)s.optDouble("y",60)*8.4f;p.setStyle(Paint.Style.STROKE);p.setColor(0xff665284);p.setStrokeWidth(5);c.drawRoundRect(tx-65,ty-65,tx+65,ty+65,20,20,p);p.setStyle(Paint.Style.FILL);if(placed){float age=motion()?Math.min(1,(SystemClock.uptimeMillis()-reactionAt)/380f):1;float ease=1-(1-age)*(1-age)*(1-age);px+=(tx-px)*ease;py+=(ty-py)*ease;}bitmap(c,art.image(art.original(s.optString("item"))),new RectF(px-58,py-58,px+58,py+58));if(placed&&motion())PlayMotion.celebration(c,p,(SystemClock.uptimeMillis()-reactionAt)/1000f,tx,ty,new int[]{0xffe4b64e,0xff55a797,0xffb881ad});return;}
 if(mode.equals("practice")){p.setColor(0xffdfe7ee);p.setStrokeWidth(2);for(int y=100;y<840;y+=100)c.drawLine(0,y,640,y,p);label(c,String.valueOf((char)('A'+index%26)),320,530,0xffd2d5dc,410);}
 if(mode.equals("dots")){for(int i=0;i<12;i++){float[]pt=point(i);p.setColor(i==dots?0xffbd5c75:0xff778491);c.drawCircle(pt[0],pt[1],i==dots?14:9,p);label(c,""+(i+1),pt[0],pt[1]-20,0xff202941,22);if(i>0&&i<=dots){float[]prev=point(i-1);p.setStrokeWidth(7);p.setColor(ink);c.drawLine(prev[0],prev[1],pt[0],pt[1],p);}}if(done){bitmap(c,art.image(art.picture(index,false)),new RectF(190,290,450,550));}return;}
 if(mode.equals("texture")){bitmap(c,art.image(art.picture(index,false)),new RectF(65,120,575,650));c.drawBitmap(marks,0,0,p);}else{c.drawBitmap(marks,0,0,p);if(mode.equals("paint"))bitmap(c,art.image(art.picture(index,true)),new RectF(15,100,625,710));}}
 float[]point(int i){double a=i*Math.PI/6-Math.PI/2;float radius=(index%3==0?i%2==0?240:130:index%3==1?210:180);return new float[]{320+(float)Math.cos(a)*radius,410+(float)Math.sin(a)*radius};}
 void drawShape(Canvas c,float x,float y,int i,Paint p){if(i==0)c.drawCircle(x,y,55,p);else if(i==1){Path tri=new Path();tri.moveTo(x,y-60);tri.lineTo(x+60,y+50);tri.lineTo(x-60,y+50);tri.close();c.drawPath(tri,p);}else c.drawRoundRect(x-55,y-55,x+55,y+55,10,10,p);}
 void placeStory(){if(placed||storyStep>=art.stories.optJSONObject(story).optJSONArray("steps").length())return;placed=true;reactionAt=SystemClock.uptimeMillis();JSONObject ep=art.stories.optJSONObject(story);prompt.setText(ep.optJSONArray("steps").optJSONObject(storyStep).optString("result"));sound.note(storyStep);storyAction.setText("Next scene");storyAction.setOnClickListener(v->{sound.tap();storyStep++;storyScene();});invalidate();}
 @Override public boolean onTouchEvent(android.view.MotionEvent e){float x=e.getX()*640/getWidth(),y=e.getY()*840/getHeight();if(nativeStage!=null&&!mode.equals("story")){x=Math.max(0,Math.min(640,(x-20)*640/600));y=Math.max(0,Math.min(840,(y-20)*840/800));}int a=e.getActionMasked();if(a==MotionEvent.ACTION_DOWN){getParent().requestDisallowInterceptTouchEvent(true);lx=x;ly=y;if(mode.equals("shape")){selected=-1;for(int i=0;i<3;i++)if(!sorted[i]&&Math.hypot(x-sx[i],y-sy[i])<80)selected=i;}if(mode.equals("paint")||mode.equals("practice")){active=new Stroke(ink,thick?30:10);active.path.moveTo(x,y);active.path.lineTo(x+.1f,y+.1f);strokes.add(active);drawStroke(active);}}if(a==MotionEvent.ACTION_MOVE||a==MotionEvent.ACTION_DOWN){if(mode.equals("fish")){foodX=x;foodY=y;}else if(mode.equals("shape")){if(selected>=0){sx[selected]=x;sy[selected]=y;}}else if(mode.equals("paint")||mode.equals("practice")){if(active!=null){active.path.lineTo(x,y);drawStroke(active);}}else if(mode.equals("texture")){p.setXfermode(new PorterDuffXfermode(PorterDuff.Mode.CLEAR));p.setStrokeWidth(86);p.setStrokeCap(Paint.Cap.ROUND);drawing.drawLine(lx,ly,x,y,p);p.setXfermode(null);}else if(mode.equals("clay")){float dx=x-lx,dy=y-ly;for(int i=0;i<24;i++){float distance=(float)Math.hypot(cx[i]-x,cy[i]-y);float weight=Math.max(0,1-distance/200);if(tool.equals("Pull")){cx[i]+=dx*weight;cy[i]+=dy*weight;}else if(tool.equals("Flatten")){cx[i]=320+(cx[i]-320)*1.005f;cy[i]=360+(cy[i]-360)*.995f;}else{cx[i]=320+(cx[i]-320)*1.006f;cy[i]=360+(cy[i]-360)*.998f;}cx[i]=Math.max(35,Math.min(605,cx[i]));cy[i]=Math.max(100,Math.min(650,cy[i]));}performHapticFeedback(HapticFeedbackConstants.CLOCK_TICK);}else if(mode.equals("story")&&!placed){px=x;py=y;}else if(mode.equals("dots")&&!done){float[]pt=point(dots);if(Math.hypot(x-pt[0],y-pt[1])<48){dots++;sound.note(dots);if(dots==12){done=true;prompt.setText("You connected every dot!");sound.win();reward("dots-"+index);}}}lx=x;ly=y;invalidate();}if(a==MotionEvent.ACTION_UP||a==MotionEvent.ACTION_CANCEL){getParent().requestDisallowInterceptTouchEvent(false);if(a==MotionEvent.ACTION_UP){performClick();if(mode.equals("shape")&&selected>=0){if(Math.hypot(x-(115+selected*200),y-590)<95){sorted[selected]=true;sound.note(selected);}else{sx[selected]=115+selected*200;sy[selected]=200;}selected=-1;if(sorted[0]&&sorted[1]&&sorted[2]&&!done){done=true;sound.win();reward("shape-0");prompt.setText("All three shapes found their homes!");}invalidate();}if(mode.equals("story")&&!placed){JSONObject s=art.stories.optJSONObject(story).optJSONArray("steps").optJSONObject(storyStep);if(Math.hypot(x-(float)s.optDouble("x")*6.4f,y-(float)s.optDouble("y")*8.4f)<100)placeStory();}if(mode.equals("texture")&&!done){int clear=0,total=0;for(int xx=80;xx<570;xx+=35)for(int yy=135;yy<650;yy+=35){total++;if(Color.alpha(marks.getPixel(xx,yy))<32)clear++;}if(clear>total*.6f){done=true;sound.win();prompt.setText("You uncovered "+art.title(index)+"!");reward("texture-"+index);}}}active=null;persist();}return true;}
